import React, { useState, useEffect, useRef } from 'react';
import '../styles/Construcao.css';

const Construcao = () => {
  const [activeTab, setActiveTab] = useState('sobre');
  const [currentSlide, setCurrentSlide] = useState(0);
  const [copiado, setCopiado] = useState(false);
  const pixRef = useRef(null);

  // Dados da construção
  const construcaoData = {
    dataPrevista: 'Dezembro 2026'
  };

  // Fotos para o carrossel (substitua pelas suas fotos)
  const carrosselFotos = [
    {
      id: 1,
      src: '../assets/fotoIgreja1.jpeg',
      titulo: 'Projeto',
      descricao: 'Fachada do Templo'
    },
    {
      id: 2,
      src: '../assets/fotoIgreja2.jpeg',
      titulo: 'Projeto',
      descricao: 'Vista da Igreja - Interna'
    },
    {
      id: 3,
      src: '../assets/fotoIgreja3.jpeg',
      titulo: 'Projeto',
      descricao: 'Vista Superior da Igreja - Interna'
    },
    {
      id: 4,
      src: '../assets/fotoIgreja4.jpeg',
      titulo: 'Projeto',
      descricao: 'Entrada do Templo'
    }
  ];

  // Galeria de fotos completa
  const fotosConstrucao = [
    ...carrosselFotos,
    {
      id: 5,
      src: 'https://images.unsplash.com/photo-1519996529937-47d6c1f2c36a?ixlib=rb-4.0.3&auto=format&fit=crop&w=500&q=80',
      titulo: 'Cobertura',
      data: '12/04/2024'
    },
    {
      id: 6,
      src: 'https://images.unsplash.com/photo-1503387762606-45b13c6fec4e?ixlib=rb-4.0.3&auto=format&fit=crop&w=500&q=80',
      titulo: 'Acabamentos',
      data: '25/04/2024'
    }
  ];

  // Dados bancários para doação
  const dadosBancarios = {
    pix: {
      chave: 'igrejaadcavallari@email.com',
      tipo: 'E-mail',
      qrCode: 'https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=igrejaadcavallari@email.com'
    },
    bancario: {
      banco: 'Banco do Brasil',
      agencia: '1234-5',
      conta: '56789-0',
      cnpj: '12.345.678/0001-90',
      favorecido: 'Igreja AD Cavallari'
    }
  };

  // SVG Icons
  const SvgIcons = {
    whatsapp: () => (
      <svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor">
        <path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893-.001-3.189-1.262-6.187-3.55-8.444"/>
      </svg>
    ),
    pix: () => (
      <svg width="24" height="24" viewBox="0 0 24 24" fill="currentColor">
        <path d="M2.534 10.467h4.4v4.4h-4.4zM17.066 10.467h4.4v4.4h-4.4zM12.534 2.534h4.4v4.4h-4.4zM12.534 18.4h4.4v4.4h-4.4zM17.066 13.867h4.4v2.2h-4.4zM2.534 13.867h4.4v2.2h-4.4zM7.2 7.2h9.6v9.6H7.2zM10.467 2.534h2.2v4.4h-2.2zM10.467 17.066h2.2v4.4h-2.2zM2.534 7.934h4.4v2.2h-4.4zM17.066 7.934h4.4v2.2h-4.4z"/>
      </svg>
    ),
    bank: () => (
      <svg width="24" height="24" viewBox="0 0 24 24" fill="currentColor">
        <path d="M21 5H3c-1.1 0-2 .9-2 2v10c0 1.1.9 2 2 2h18c1.1 0 2-.9 2-2V7c0-1.1-.9-2-2-2zM3 17V7h18v10H3zm6-8h2v6H9zm4 0h2v6h-2z"/>
      </svg>
    ),
    copy: () => (
      <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor">
        <path d="M16 1H4c-1.1 0-2 .9-2 2v14h2V3h12V1zm3 4H8c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h11c1.1 0 2-.9 2-2V7c0-1.1-.9-2-2-2zm0 16H8V7h11v14z"/>
      </svg>
    ),
    construction: () => (
      <svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor">
        <path d="M17.5 10.5c0 1.65-1.35 3-3 3s-3-1.35-3-3 1.35-3 3-3 3 1.35 3 3zm-3-8c-4.05 0-7.27 3.11-7.68 7.08L2 18.5l1.41 1.41 4.09-4.09A7.015 7.015 0 0 0 14.5 17c3.86 0 7-3.14 7-7s-3.14-7-7-7zm-7 7c0-3.86 3.14-7 7-7s7 3.14 7 7-3.14 7-7 7-7-3.14-7-7z"/>
      </svg>
    ),
    worker: () => (
      <svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor">
        <path d="M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z"/>
      </svg>
    ),
    paint: () => (
      <svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor">
        <path d="M18 4V3c0-.55-.45-1-1-1H5c-.55 0-1 .45-1 1v4c0 .55.45 1 1 1h12c.55 0 1-.45 1-1V6h1v4H9v11c0 .55.45 1 1 1h2c.55 0 1-.45 1-1v-9h8V4h-3z"/>
      </svg>
    ),
    sound: () => (
      <svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor">
        <path d="M3 9v6h4l5 5V4L7 9H3zm13.5 3c0-1.77-1.02-3.29-2.5-4.03v8.05c1.48-.73 2.5-2.25 2.5-4.02zM14 3.23v2.06c2.89.86 5 3.54 5 6.71s-2.11 5.85-5 6.71v2.06c4.01-.91 7-4.49 7-8.77s-2.99-7.86-7-8.77z"/>
      </svg>
    ),
    kids: () => (
      <svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor">
        <path d="M12.5 6.5c0-1.1.9-2 2-2s2 .9 2 2-.9 2-2 2-2-.9-2-2zm6 10.5h-2v1.25c0 1.1-.9 2-2 2s-2-.9-2-2V17h-2v1.25c0 1.1-.9 2-2 2s-2-.9-2-2V17H5.5v-2.5h14v2.5zm-8-7.5c0-2.5 3-2.5 3-5 0-1.1-.9-2-2-2s-2 .9-2 2h-2c0-2.21 1.79-4 4-4s4 1.79 4 4c0 2.5-3 2.5-3 5z"/>
      </svg>
    )
  };

  const copiarPix = async () => {
    try {
      await navigator.clipboard.writeText(dadosBancarios.pix.chave);
      setCopiado(true);
      setTimeout(() => setCopiado(false), 3000);
    } catch (err) {
      console.error('Falha ao copiar: ', err);
    }
  };

  const copiarDadosBancarios = async (texto) => {
    try {
      await navigator.clipboard.writeText(texto);
      setCopiado(true);
      setTimeout(() => setCopiado(false), 3000);
    } catch (err) {
      console.error('Falha ao copiar: ', err);
    }
  };

  // Auto-play do carrossel
  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentSlide((prev) => (prev + 1) % carrosselFotos.length);
    }, 5000);

    return () => clearInterval(interval);
  }, [carrosselFotos.length]);

  const nextSlide = () => {
    setCurrentSlide((prev) => (prev + 1) % carrosselFotos.length);
  };

  const prevSlide = () => {
    setCurrentSlide((prev) => (prev - 1 + carrosselFotos.length) % carrosselFotos.length);
  };

  const goToSlide = (index) => {
    setCurrentSlide(index);
  };

  return (
    <div className="pagina-construcao">
      {/* Hero Section com Carrossel */}
      <section className="construcao-hero">
        <div className="container">
          <div className="hero-content">
            <h1>🏗️ Novo Templo AD Cavallari</h1>
            <p className="hero-subtitle">Construindo juntos uma casa de adoração e milagres</p>
            
            {/* Carrossel de Fotos */}
            <div className="carrossel-container">
              <div className="carrossel">
                <div 
                  className="carrossel-track"
                  style={{ transform: `translateX(-${currentSlide * 100}%)` }}
                >
                  {carrosselFotos.map((foto, index) => (
                    <div key={foto.id} className="carrossel-slide">
                      <img src={foto.src} alt={foto.titulo} />
                      <div className="carrossel-content">
                        <h3>{foto.titulo}</h3>
                        <p>{foto.descricao}</p>
                      </div>
                    </div>
                  ))}
                </div>
                
                {/* Botões de navegação */}
                <button className="carrossel-btn carrossel-prev" onClick={prevSlide}>
                  ‹
                </button>
                <button className="carrossel-btn carrossel-next" onClick={nextSlide}>
                  ›
                </button>
                
                {/* Indicadores */}
                <div className="carrossel-indicators">
                  {carrosselFotos.map((_, index) => (
                    <button
                      key={index}
                      className={`indicator ${index === currentSlide ? 'active' : ''}`}
                      onClick={() => goToSlide(index)}
                    />
                  ))}
                </div>
              </div>
              
              <div className="carrossel-info">
                <span>📅 Previsão de conclusão: {construcaoData.dataPrevista}</span>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* Navegação por Abas */}
      <section className="construcao-tabs">
        <div className="container">
          <div className="tabs-navigation">
            <button 
              className={`tab-btn ${activeTab === 'sobre' ? 'active' : ''}`}
              onClick={() => setActiveTab('sobre')}
            >
              📖 Sobre a Obra
            </button>
            <button 
              className={`tab-btn ${activeTab === 'galeria' ? 'active' : ''}`}
              onClick={() => setActiveTab('galeria')}
            >
              🏗️ Galeria
            </button>
            <button 
              className={`tab-btn ${activeTab === 'doar' ? 'active' : ''}`}
              onClick={() => setActiveTab('doar')}
            >
              💝 Fazer Doação
            </button>
          </div>
        </div>
      </section>

      {/* Conteúdo das Abas */}
      <section className="construcao-conteudo">
        <div className="container">
          
          {/* ABA: SOBRE A OBRA */}
          {activeTab === 'sobre' && (
            <div className="tab-content sobre-content">
              <div className="sobre-grid">
                <div className="sobre-texto">
                  <h2>Uma Casa para a Glória de Deus</h2>
                  <p>
                    Estamos construindo um novo templo para abençoar nossa comunidade e 
                    expandir o Reino de Deus. Este será um lugar de encontro, adoração e 
                    transformação de vidas.
                  </p>
                  
                  <div className="detalhes-obra">
                    <h3>📐 Detalhes da Construção</h3>
                    <ul>
                      <li>✅ <strong>Área total:</strong> 440m²</li>
                      <li>✅ <strong>Capacidade:</strong> 350 pessoas</li>
                      <li>✅ <strong>Salas:</strong> Escola Bíblica, Administração, Sala Kids</li>
                      <li>✅ <strong>Banheiros:</strong> 3 Banheiros</li>
                      <li>✅ <strong>Acessibilidade:</strong> Total</li>
                    </ul>
                  </div>

                  <div className="versiculo">
                    <blockquote>
                      "Assim diz o Senhor dos Exércitos: A glória desta última casa será maior 
                      do que a da primeira, diz o Senhor dos Exércitos; e neste lugar darei a paz, 
                      diz o Senhor dos Exércitos."
                    </blockquote>
                    <cite>Ageu 2:9</cite>
                  </div>
                </div>
                
                <div className="sobre-imagem">
                  <img 
                    src="https://images.unsplash.com/photo-1545235617-9465d2a55698?ixlib=rb-4.0.3&auto=format&fit=crop&w=600&q=80" 
                    alt="Projeto do novo templo" 
                  />
                </div>
              </div>
            </div>
          )}

          {/* ABA: GALERIA */}
          {activeTab === 'galeria' && (
            <div className="tab-content galeria-content">
              <h2>📸 Acompanhe a Evolução da Obra</h2>
              <p>Veja como está progredindo a construção do nosso novo templo</p>
              
              <div className="galeria-grid">
                {fotosConstrucao.map(foto => (
                  <div key={foto.id} className="galeria-item">
                    <div className="galeria-imagem">
                      <img src={foto.src} alt={foto.titulo} />
                      <div className="galeria-overlay">
                        <div className="galeria-info">
                          <h4>{foto.titulo}</h4>
                          <span>{foto.data || foto.descricao}</span>
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* ABA: DOAÇÕES - ATUALIZADA */}
          {activeTab === 'doar' && (
            <div className="tab-content doacao-content">
              <div className="doacao-header">
                <h2>💝 Seja um Construtor com a Gente</h2>
                <p>
                  Sua contribuição é essencial para concluirmos esta obra abençoada. 
                  Cada oferta é um tijolo na construção do Reino de Deus.
                </p>
              </div>

              <div className="doacao-grid">
                {/* PIX */}
                <div className="metodo-pagamento">
                  <div className="metodo-header">
                    <div className="metodo-icon">
                      <SvgIcons.pix />
                    </div>
                    <h3>PIX - Mais Rápido e Prático</h3>
                  </div>
                  
                  <div className="pix-container">
                    <div className="qr-code">
                      <img src={dadosBancarios.pix.qrCode} alt="QR Code PIX" />
                      <div className="qr-info">
                        <p>Escaneie o QR Code com seu app bancário</p>
                      </div>
                      <div className="pix-chave-mobile">
                        <div className="chave-info">
                          <strong>Chave PIX ({dadosBancarios.pix.tipo}):</strong>
                          <div className="chave-valor" ref={pixRef}>
                            {dadosBancarios.pix.chave}
                          </div>
                        </div>
                        <button 
                          className="btn-copiar"
                          onClick={copiarPix}
                        >
                          <SvgIcons.copy /> {copiado ? 'Copiado!' : 'Copiar Chave'}
                        </button>
                      </div>
                    </div>
                    
                    <div className="pix-chave-desktop">
                      <div className="chave-info">
                        <strong>Chave PIX ({dadosBancarios.pix.tipo}):</strong>
                        <div className="chave-valor" ref={pixRef}>
                          {dadosBancarios.pix.chave}
                        </div>
                      </div>
                      <button 
                        className="btn-copiar"
                        onClick={copiarPix}
                      >
                        <SvgIcons.copy /> {copiado ? 'Copiado!' : 'Copiar Chave'}
                      </button>
                    </div>
                  </div>
                </div>

                {/* Transferência Bancária */}
                <div className="metodo-pagamento">
                  <div className="metodo-header">
                    <div className="metodo-icon">
                      <SvgIcons.bank />
                    </div>
                    <h3>Transferência Bancária</h3>
                  </div>
                  
                  <div className="dados-bancarios">
                    <div className="dado-item">
                      <strong>Banco:</strong>
                      <span>{dadosBancarios.bancario.banco}</span>
                      <button 
                        className="btn-copiar pequeno"
                        onClick={() => copiarDadosBancarios(dadosBancarios.bancario.banco)}
                      >
                        <SvgIcons.copy />
                      </button>
                    </div>
                    
                    <div className="dado-item">
                      <strong>Agência:</strong>
                      <span>{dadosBancarios.bancario.agencia}</span>
                      <button 
                        className="btn-copiar pequeno"
                        onClick={() => copiarDadosBancarios(dadosBancarios.bancario.agencia)}
                      >
                        <SvgIcons.copy />
                      </button>
                    </div>
                    
                    <div className="dado-item">
                      <strong>Conta:</strong>
                      <span>{dadosBancarios.bancario.conta}</span>
                      <button 
                        className="btn-copiar pequeno"
                        onClick={() => copiarDadosBancarios(dadosBancarios.bancario.conta)}
                      >
                        <SvgIcons.copy />
                      </button>
                    </div>
                    
                    <div className="dado-item">
                      <strong>Favorecido:</strong>
                      <span>{dadosBancarios.bancario.favorecido}</span>
                      <button 
                        className="btn-copiar pequeno"
                        onClick={() => copiarDadosBancarios(dadosBancarios.bancario.favorecido)}
                      >
                        <SvgIcons.copy />
                      </button>
                    </div>
                    
                    <div className="dado-item">
                      <strong>CNPJ:</strong>
                      <span>{dadosBancarios.bancario.cnpj}</span>
                      <button 
                        className="btn-copiar pequeno"
                        onClick={() => copiarDadosBancarios(dadosBancarios.bancario.cnpj)}
                      >
                        <SvgIcons.copy />
                      </button>
                    </div>
                  </div>
                </div>
              </div>

              {/* Benefícios da Doação */}
              <div className="beneficios-doacao">
                <h3>🎁 Sua doação ajuda em:</h3>
                <div className="beneficios-grid">
                  <div className="beneficio-item">
                    <div className="beneficio-icon">
                      <SvgIcons.construction />
                    </div>
                    <span>Materiais de construção</span>
                  </div>
                  <div className="beneficio-item">
                    <div className="beneficio-icon">
                      <SvgIcons.worker />
                    </div>
                    <span>Mão de obra especializada</span>
                  </div>
                  <div className="beneficio-item">
                    <div className="beneficio-icon">
                      <SvgIcons.paint />
                    </div>
                    <span>Acabamentos e mobiliário</span>
                  </div>
                  <div className="beneficio-item">
                    <div className="beneficio-icon">
                      <SvgIcons.sound />
                    </div>
                    <span>Sistema de som e iluminação</span>
                  </div>
                  <div className="beneficio-item">
                    <div className="beneficio-icon">
                      <SvgIcons.kids />
                    </div>
                    <span>Área infantil e educacional</span>
                  </div>
                </div>
              </div>

              {/* Aviso de Confirmação */}
              <div className="aviso-doacao">
                <div className="aviso-icon">
                  <SvgIcons.whatsapp />
                </div>
                <div className="aviso-content">
                  <h4>Envie o comprovante</h4>
                  <p>
                    Após realizar a doação, envie o comprovante para nosso WhatsApp 
                    para que possamos agradecer e registrar sua contribuição.
                  </p>
                  <a 
                    href="https://wa.me/5511999999999?text=Olá! Acabei de fazer uma doação para a construção do novo templo."
                    className="btn-whatsapp"
                    target="_blank"
                    rel="noopener noreferrer"
                  >
                    <SvgIcons.whatsapp /> Enviar Comprovante
                  </a>
                </div>
              </div>
            </div>
          )}
        </div>
      </section>

      {/* CTA Final */}
      <section className="construcao-cta">
        <div className="container">
          <div className="cta-content">
            <h2>Juntos na Obra do Senhor</h2>
            <p>Sua participação faz parte desta história de fé e milagres</p>
            <button 
              className="btn-cta"
              onClick={() => setActiveTab('doar')}
            >
              Quero Contribuir
            </button>
          </div>
        </div>
      </section>

      {/* Toast de Cópia */}
      {copiado && (
        <div className="toast-copiada">
          ✅ Chave PIX copiada para a área de transferência!
        </div>
      )}
    </div>
  );
};

export default Construcao;
